//! Parity: pure-data `Pipe` attributes match Python for the synthetic constructor calls in
//! `fixtures/pipes.json` (generated by `fixtures/gen_pipes.py`).

mod common;

use chrono::TimeDelta;
use meerschaum_core::pipe::{
    ChunkInterval, ChunkIntervalArg, Pipe, PipeDefaults, PipeError, truncate_item_name,
};
use meerschaum_core::{Map, Value};

fn defaults() -> PipeDefaults {
    PipeDefaults {
        // The generator disables the pipes cache with `MRSM_CONFIG`.
        cache_enabled: false,
        ..PipeDefaults::default()
    }
}

fn py_error_name(e: &PipeError) -> &'static str {
    match e {
        PipeError::MissingKeys | PipeError::NegationPrefix(_) | PipeError::Truncate(_) => {
            "Exception"
        }
        PipeError::TypeError(_) => "TypeError",
        PipeError::ValueError(_) => "ValueError",
    }
}

fn ok(v: Value) -> Value {
    let mut m = Map::new();
    m.insert("ok".into(), v);
    Value::Map(m)
}

fn err(e: &PipeError) -> Value {
    let mut m = Map::new();
    m.insert("error".into(), Value::from(py_error_name(e)));
    Value::Map(m)
}

fn attempt(r: Result<Value, PipeError>) -> Value {
    match r {
        Ok(v) => ok(v),
        Err(e) => err(&e),
    }
}

fn chunk_value(c: ChunkInterval) -> Value {
    let mut m = Map::new();
    match c {
        ChunkInterval::Delta(d) => {
            m.insert("delta_us".into(), Value::Int(d.num_microseconds().unwrap()));
        }
        ChunkInterval::Int(i) => {
            m.insert("int".into(), Value::Int(i));
        }
    }
    Value::Map(m)
}

fn refs(r: Result<Vec<Option<Pipe>>, PipeError>) -> Value {
    attempt(r.map(|pipes| {
        Value::List(
            pipes
                .into_iter()
                .map(|p| p.map_or(Value::Null, |p| Value::Map(p.keys())))
                .collect(),
        )
    }))
}

fn describe(pipe: &Pipe) -> Value {
    let d = defaults();
    let mut out = Map::new();
    out.insert("str".into(), Value::Str(pipe.to_string()));
    out.insert("keys".into(), Value::Map(pipe.keys()));
    out.insert("state".into(), Value::Map(pipe.to_state()));
    out.insert("parameters".into(), Value::Map(pipe.parameters().clone()));
    out.insert("columns".into(), Value::Map(pipe.columns()));
    out.insert("dtypes".into(), Value::Map(pipe.dtypes()));
    out.insert("tags".into(), pipe.tags());
    out.insert("target".into(), Value::Str(pipe.target(None).unwrap()));
    let mut flags = Map::new();
    flags.insert("upsert".into(), pipe.upsert().into());
    flags.insert("static".into(), pipe.is_static().into());
    flags.insert("autoincrement".into(), pipe.autoincrement().into());
    flags.insert("autotime".into(), pipe.autotime().into());
    flags.insert("enforce".into(), pipe.enforce().into());
    flags.insert("null_indices".into(), pipe.null_indices().into());
    flags.insert("mixed_numerics".into(), pipe.mixed_numerics().into());
    out.insert("flags".into(), Value::Map(flags));
    out.insert("cache".into(), pipe.cache.into());
    let mut indices = pipe.indices();
    if let Some(Value::List(unique)) = indices.get_mut("unique") {
        unique.sort_by_key(|v| v.to_json_string());
    }
    out.insert("indices".into(), Value::Map(indices));
    out.insert(
        "precision".into(),
        attempt(pipe.precision(&d).map(|p| p.to_value())),
    );
    let mut chunk = Map::new();
    for (name, arg) in [
        ("none", None),
        (
            "delta_90m",
            Some(ChunkIntervalArg::Delta(TimeDelta::minutes(90))),
        ),
        ("int_7", Some(ChunkIntervalArg::Int(7))),
    ] {
        chunk.insert(
            name.into(),
            attempt(pipe.get_chunk_interval(arg, &d).map(chunk_value)),
        );
    }
    out.insert("chunk".into(), Value::Map(chunk));
    out.insert("parents".into(), refs(pipe.parents(&d)));
    out.insert("children".into(), refs(pipe.children(&d)));
    out.insert("references".into(), refs(pipe.references(&d)));
    Value::Map(out)
}

#[test]
fn pipe_attributes_match_python() {
    let fixture = common::load_fixture("pipes.json");
    for case in fixture.get("cases").and_then(Value::as_list).unwrap() {
        let call = case.get("case").unwrap();
        let args = call
            .get("args")
            .and_then(Value::as_list)
            .cloned()
            .unwrap_or_default();
        let kwargs = call.get("kwargs").map(Value::to_map).unwrap_or_default();
        let result = Pipe::from_call(&args, &kwargs, &defaults());
        let context = call.to_json_string();
        match (result, case.get("error")) {
            (Err(e), Some(expected)) => {
                assert_eq!(Some(py_error_name(&e)), expected.as_str(), "{context}");
            }
            (Err(e), None) => panic!("{context}: Rust failed with {e}"),
            (Ok(_), Some(expected)) => panic!("{context}: Python raised {expected}"),
            (Ok(pipe), None) => {
                let expected = case.get("pipe").unwrap();
                let actual = describe(&pipe);
                for (k, v) in expected.as_map().unwrap() {
                    common::assert_same(
                        actual.get(k).unwrap(),
                        v,
                        &format!("{context} attribute '{k}'"),
                    );
                }
            }
        }
    }
}

#[test]
fn truncation_matches_python() {
    let fixture = common::load_fixture("pipes.json");
    for t in fixture.get("truncate").and_then(Value::as_list).unwrap() {
        let item = t.get("item").and_then(Value::as_str).unwrap();
        let flavor = t.get("flavor").and_then(Value::as_str).unwrap();
        match (truncate_item_name(item, flavor), t.get("ok")) {
            (Ok(s), Some(expected)) => assert_eq!(Some(s.as_str()), expected.as_str(), "{item}"),
            (Err(_), None) => {}
            (r, e) => panic!("{item} {flavor}: {r:?} vs {e:?}"),
        }
    }
}

#[test]
fn equality_and_hash_use_keys_only() {
    use std::collections::HashSet;
    let a = Pipe::builder("sql:main", "m")
        .parameters(Value::from_json_str(r#"{"a": 1}"#).unwrap().to_map())
        .build()
        .unwrap();
    let b = Pipe::new("sql:main", "m").unwrap();
    let c = Pipe::builder("sql:main", "m")
        .instance("sql:other")
        .build()
        .unwrap();
    assert_eq!(a, b);
    assert_ne!(a, c);
    let set: HashSet<Pipe> = [a, b, c].into_iter().collect();
    assert_eq!(set.len(), 2);
}
